from collections import deque, Counter

# Let me check for enclosed background regions (holes)
# The input has background 1, and we're looking for regions of 1 that don't touch border

def find_enclosed_regions(grid, bg_color):
    """Find regions of bg_color that don't touch the border"""
    h, w = len(grid), len(grid[0])

    # BFS from all border cells to mark reachable bg regions
    reachable = [[False]*w for _ in range(h)]
    queue = deque()

    # Add all border cells that are bg
    for i in range(h):
        for j in range(w):
            if (i == 0 or i == h-1 or j == 0 or j == w-1):
                if grid[i][j] == bg_color:
                    reachable[i][j] = True
                    queue.append((i, j))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w:
                if not reachable[nr][nc] and grid[nr][nc] == bg_color:
                    reachable[nr][nc] = True
                    queue.append((nr, nc))

    # Find enclosed regions (bg cells not reachable from border)
    enclosed = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == bg_color and not reachable[i][j]:
                enclosed.append((i, j))

    return enclosed

